"use strict";
(()=>{const input=document.getElementById('term-search'),count=document.getElementById('term-count'),empty=document.getElementById('no-results'),terms=[...document.querySelectorAll('.term')];if(!input)return;function update(){const q=input.value.trim().toLocaleLowerCase();let n=0;terms.forEach(term=>{const match=term.textContent.toLocaleLowerCase().includes(q);term.hidden=!match;if(match)n++;});count.textContent=q?'找到 '+n+' / '+terms.length+' 個名詞':'共 '+terms.length+' 個名詞';empty.hidden=n!==0;}input.addEventListener('input',update);input.addEventListener('search',update);update();})();
